import { randomBytes } from 'node:crypto';
import type { Readable } from 'node:stream';
import type { AppConfig } from '../../config/env.js';
import { LocalDocumentStorage } from './localStorage.js';

/**
 * Private document storage (bill photographs and PDFs).
 *
 * Business code depends only on this interface, never on a provider. Rules for every adapter:
 *  - objects are PRIVATE: no public URLs, no static hosting of the storage location;
 *  - keys are generated by the server (`newStorageKey()`); user-supplied names are never paths;
 *  - `put` must be all-or-nothing: after a failed `put` no readable object exists under the key.
 *
 * Implemented: `local` (a directory on the API server's disk). A private object-storage adapter
 * (S3-compatible, Azure Blob, GCS, ...) can be added by implementing this interface and wiring it
 * in `createDocumentStorage`; see docs/architecture.md → "Bill documents" for the planned settings.
 */
export interface DocumentStorage {
  readonly driver: string;
  /** Stores bytes under a NEW key. Fails if the key already exists. */
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  /** Opens an object for streaming. Throws StorageObjectMissing when it does not exist. */
  open(key: string): Promise<{ stream: Readable; sizeBytes: number }>;
  /** Deletes an object. Deleting a missing object is not an error. */
  delete(key: string): Promise<void>;
  exists(key: string): Promise<boolean>;
  /** Every stored object (for reconciliation). Entries whose name is not a valid key are reported too. */
  list(): AsyncIterable<StoredObject>;
  /**
   * A short-lived, pre-authorised URL for providers that support one (e.g. signed object-storage
   * URLs). Returns null when the provider has none; the API then streams the file itself after
   * its own authorisation checks. Callers must authorise the user BEFORE asking for a URL.
   */
  createAccessUrl(key: string, options: { expiresInSeconds: number; fileName: string; download: boolean }): Promise<string | null>;
}

export interface StoredObject {
  /** The storage key, or the raw relative name for stray entries that are not valid keys. */
  key: string;
  validKey: boolean;
  sizeBytes: number;
  modifiedAt: Date;
}

export class StorageObjectMissing extends Error {
  constructor(key: string) {
    super(`Stored object not found: ${key}`);
    this.name = 'StorageObjectMissing';
  }
}

/** Lower-case alphanumeric segments separated by "/" (no dots, so no traversal is expressible). */
export const STORAGE_KEY_PATTERN = /^[a-z0-9]+(\/[a-z0-9]+)*$/;

export function isValidStorageKey(key: string): boolean {
  return key.length <= 200 && STORAGE_KEY_PATTERN.test(key);
}

/** New random key, e.g. "3f/9c1e…" (128 random bits; the 2-character prefix spreads files over folders). */
export function newStorageKey(): string {
  const id = randomBytes(16).toString('hex');
  return `${id.slice(0, 2)}/${id}`;
}

export function createDocumentStorage(config: AppConfig['documentStorage']): DocumentStorage {
  switch (config.driver) {
    case 'local':
      return new LocalDocumentStorage(config.directory);
  }
}
